### 3️⃣ Implementar o servidor (`server.js`)
```javascript
// server.js
const express = require('express');
const app = express();
app.use(express.json());

let signals = []; // armazenamento em memória
let nextId = 1;

/**
 * @api {get} /health Checagem de saúde
 * @apiSuccess {String} status "ok"
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

/**
 * @api {get} /signals Listar todos os sinais
 * @apiSuccess {Object[]} signals Lista de sinais
 */
app.get('/signals', (req, res) => {
  res.json(signals);
});

/**
 * @api {post} /signals Criar novo sinal
 * @apiBody {String} message Mensagem do sinal
 * @apiSuccess {Object} signal Sinal criado
 */
app.post('/signals', (req, res) => {
  const { message } = req.body;
  if (!message || typeof message !== 'string') {
    return res.status(400).json({ error: 'Campo "message" é obrigatório e deve ser string.' });
  }
  const signal = { id: nextId++, message, timestamp: new Date().toISOString() };
  signals.push(signal);
  res.status(201).json(signal);
});

/**
 * @api {delete} /signals/:id Remover sinal
 * @apiParam {Number} id ID do sinal a ser removido
 * @apiSuccess {String} result Mensagem de sucesso
 */
app.delete('/signals/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  const index = signals.findIndex(s => s.id === id);
  if (index === -1) {
    return res.status(404).json({ error: 'Sinal não encontrado.' });
  }
  signals.splice(index, 1);
  res.json({ result: 'Sinal removido.' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Servidor rodando na porta ${PORT}`);
});

module.exports = app; // Exporta para os testes
```
