### 4️⃣ Criar testes automatizados (`test/server.test.js`)
```javascript
// test/server.test.js
const request = require('supertest');
const app = require('../server');

describe('API de Sinais Aave', () => {
  test('GET /health deve retornar status ok', async () => {
    const res = await request(app).get('/health');
    expect(res.statusCode).toBe(200);
    expect(res.body).toEqual({ status: 'ok' });
  });

  test('POST /signals cria um sinal válido', async () => {
    const payload = { message: 'Compra AAVE' };
    const res = await request(app).post('/signals').send(payload);
    expect(res.statusCode).toBe(201);
    expect(res.body).toMatchObject(payload);
    expect(res.body).toHaveProperty('id');
    expect(res.body).toHaveProperty('timestamp');
  });

  test('GET /signals retorna lista contendo o sinal criado', async () => {
    const res = await request(app).get('/signals');
    expect(res.statusCode).toBe(200);
    expect(Array.isArray(res.body)).toBe(true);
    expect(res.body.length).toBeGreaterThan(0);
    expect(res.body[0]).toHaveProperty('message', 'Compra AAVE');
  });

  test('DELETE /signals/:id remove o sinal', async () => {
    // Primeiro cria um novo sinal para deletar
    const createRes = await request(app).post('/signals').send({ message: 'Venda AAVE' });
    const id = createRes.body.id;

    const delRes = await request(app).delete(`/signals/${id}`);
    expect(delRes.statusCode).toBe(200);
    expect(delRes.body).toEqual({ result: 'Sinal removido.' });

    // Verifica que o sinal não está mais na lista
    const listRes = await request(app).get('/signals');
    const exists = listRes.body.some(s => s.id === id);
    expect(exists).toBe(false);
  });

  test('POST /signals com payload inválido retorna 400', async () => {
    const res = await request(app).post('/signals').send({ msg: 'sem campo correto' });
    expect(res.statusCode).toBe(400);
    expect(res.body).toHaveProperty('error');
  });
});
```
